-- =============================================================
-- BFA-Scout — Phase 5a reseed migration
-- Generated by migrations/_generate_phase_5a.py from v2-LOCKED
-- taxonomy. Do not edit by hand: re-run the generator instead.
-- =============================================================
-- Effects:
--   1. Pre-flight: aborts if evaluation_scores has rows or any
--      evaluation uses the legacy recommendation = 'not_ready'.
--   2. Reseeds criteria (55 items) and
--      position_group_criteria (303 mappings).
--   3. Adds 4 columns to evaluations (NT readiness section).
--   4. Drops + re-adds evaluations_recommendation_check with
--      the new value set (loses 'not_ready', gains 'not_at_level').
--   5. Audit assertions enforce per-position counts before COMMIT.
-- =============================================================

\set ON_ERROR_STOP on
\timing on

-- ─── Pre-flight (no transaction yet — fail fast before locking rows) ───
DO $$
DECLARE
  s_count INT;
  bad_recs INT;
BEGIN
  SELECT COUNT(*) INTO s_count FROM evaluation_scores;
  IF s_count > 0 THEN
    RAISE EXCEPTION 'ABORT: evaluation_scores has % row(s); reseed would orphan or violate FKs', s_count;
  END IF;
  SELECT COUNT(*) INTO bad_recs FROM evaluations WHERE recommendation = 'not_ready';
  IF bad_recs > 0 THEN
    RAISE EXCEPTION 'ABORT: % evaluation row(s) use legacy recommendation = not_ready; migrate them before re-running', bad_recs;
  END IF;
END $$;

BEGIN;

