-- ─── NT-readiness columns + recommendation CHECK swap ───
ALTER TABLE evaluations
  ADD COLUMN nt_readiness_level VARCHAR(16)
    CHECK (nt_readiness_level IN ('senior','u23','u20','u17','not_ready') OR nt_readiness_level IS NULL),
  ADD COLUMN eligibility_status VARCHAR(32)
    CHECK (eligibility_status IN ('bahraini','foreign_residency','foreign_ancestry','foreign_other','not_eligible','unknown') OR eligibility_status IS NULL),
  ADD COLUMN eligibility_notes  TEXT,
  ADD COLUMN comparable_player  VARCHAR(255);

ALTER TABLE evaluations DROP CONSTRAINT evaluations_recommendation_check;
ALTER TABLE evaluations ADD CONSTRAINT evaluations_recommendation_check
  CHECK (recommendation IN ('call_up','shortlist','monitor','not_at_level','release') OR recommendation IS NULL);

-- ─── Audit: assert each position-group's per-category counts match the v2 spec ───
DO $$
DECLARE
  r RECORD;
  expected JSONB := jsonb_build_object(
    'GK', jsonb_build_object('tech',10,'tact',5,'phys',3,'ment',6,'total',24),
    'CB', jsonb_build_object('tech',9,'tact',18,'phys',9,'ment',6,'total',42),
    'FB', jsonb_build_object('tech',10,'tact',18,'phys',8,'ment',6,'total',42),
    'DM', jsonb_build_object('tech',9,'tact',18,'phys',7,'ment',6,'total',40),
    'CM', jsonb_build_object('tech',10,'tact',16,'phys',5,'ment',6,'total',37),
    'AM', jsonb_build_object('tech',14,'tact',16,'phys',6,'ment',6,'total',42),
    'W', jsonb_build_object('tech',9,'tact',16,'phys',7,'ment',6,'total',38),
    'ST', jsonb_build_object('tech',9,'tact',15,'phys',8,'ment',6,'total',38)
  );
BEGIN
  FOR r IN
    SELECT pg.code AS grp,
           COUNT(*) FILTER (WHERE c.code LIKE 'tech_%') AS tech,
           COUNT(*) FILTER (WHERE c.code LIKE 'tact_%') AS tact,
           COUNT(*) FILTER (WHERE c.code LIKE 'phys_%') AS phys,
           COUNT(*) FILTER (WHERE c.code LIKE 'ment_%') AS ment,
           COUNT(*)                                     AS total
    FROM position_groups pg
    LEFT JOIN position_group_criteria pgc ON pgc.position_group_id = pg.id
    LEFT JOIN criteria c                  ON c.id = pgc.criterion_id
    GROUP BY pg.code, pg.sort_order
    ORDER BY pg.sort_order
  LOOP
    IF (expected->r.grp->>'tech')::int  != r.tech
    OR (expected->r.grp->>'tact')::int  != r.tact
    OR (expected->r.grp->>'phys')::int  != r.phys
    OR (expected->r.grp->>'ment')::int  != r.ment
    OR (expected->r.grp->>'total')::int != r.total THEN
      RAISE EXCEPTION 'AUDIT FAIL %: got tech=% tact=% phys=% ment=% total=% (expected %)',
        r.grp, r.tech, r.tact, r.phys, r.ment, r.total, expected->r.grp;
    END IF;
  END LOOP;
  RAISE NOTICE 'AUDIT PASS — all 8 position groups match v2-LOCKED counts';
END $$;

-- ─── Human-eyeball audit table (printed before COMMIT) ───
SELECT pg.code AS grp,
       COUNT(*) FILTER (WHERE c.code LIKE 'tech_%') AS tech,
       COUNT(*) FILTER (WHERE c.code LIKE 'tact_%') AS tact,
       COUNT(*) FILTER (WHERE c.code LIKE 'phys_%') AS phys,
       COUNT(*) FILTER (WHERE c.code LIKE 'ment_%') AS ment,
       COUNT(*)                                     AS total
FROM position_groups pg
LEFT JOIN position_group_criteria pgc ON pgc.position_group_id = pg.id
LEFT JOIN criteria c                  ON c.id = pgc.criterion_id
GROUP BY pg.code, pg.sort_order
ORDER BY pg.sort_order;

COMMIT;
